async function persist(error){
 const output={error:error?String(error):null,gates,coverage,inputs};
 // Persist known receipts immediately even if CDP becomes unresponsive during
 // later DOM/screenshot collection. Never lose completed gates on timeout.
 fs.writeFileSync(path.join(reportDir,error?'failure-receipts.json':'causal-gate-receipts.json'),JSON.stringify({...output,capturePending:true},null,2));
 try{Object.assign(output,{dom:await evaluate('document.body.innerText'),http:await evaluate('window.__combatHttp'),nativeInputs:await evaluate('window.__combatInputs'),completedReports:await evaluate('window.__combatCompleted'),comparisons:await evaluate('window.__combatComparisons'),buildState:await evaluate("({state:document.querySelector('#status').dataset.buildState,classKey:document.querySelector('#classKey').value,spec:document.querySelector('#spec').value,dialog:document.querySelector('#presetDialog').open})")});if(error){const shot=await command('Page.captureScreenshot',{format:'png',captureBeyondViewport:false});fs.writeFileSync(path.join(screenshotDir,'combat-'+stamp+'-failure.png'),Buffer.from(shot.data,'base64'),{flag:'wx'});}}catch(failure){output.captureFailure=String(failure);}
 fs.writeFileSync(path.join(reportDir,error?'failure-receipts.json':'causal-gate-receipts.json'),JSON.stringify(output,null,2));
}
// Finish causal receipts before the shell's300s backstop can terminate Node.
// The bounded deadline is failure, never a skipped gate or successful timeout.
let deadlineTimer,deadlineExpired=false;
const deadline=new Promise((_,reject)=>{deadlineTimer=setTimeout(()=>{deadlineExpired=true;reject(Error('Combat browser internal270s deadline; unfinished gates failed, causal evidence retained.'));},270000);});
Promise.race([main(),deadline]).then(()=>persist()).catch(async error=>{console.error(error);process.exitCode=1;const hardStop=setTimeout(()=>process.exit(1),15000);try{await persist(error);}finally{clearTimeout(hardStop);}}).finally(()=>{clearTimeout(deadlineTimer);try{ws?.close();}catch{}proc.kill();if(deadlineExpired)setTimeout(()=>process.exit(1),1000);});
